internal static class MixerR20 {
 internal static void Validate(GraphNode15 n){if(n.Kind!=GraphKind15.Mixer)return;var s=n.MixerR20;if(s==null||s.Sources==null||s.Cues==null||s.Sources.Count>256||!Enum.IsDefined(typeof(MixerModeR20),s.Mode)||new[]{s.Hardness,s.Transition,s.Cycle,s.MinimumSignalR21}.Any(v=>double.IsNaN(v)||double.IsInfinity(v))||s.MinimumSignalR21<0||s.MinimumSignalR21>60||s.Hardness<0||s.Hardness>1||s.Transition<0||s.Transition>60||s.Cycle<.001||s.Cycle>4096||s.Sources.Any(x=>x==null||x.Node==null||double.IsNaN(x.Min)||double.IsNaN(x.Max)||x.Min<0||x.Max>127||x.Min>x.Max)||s.Cues.Any(c=>c==null||double.IsNaN(c.Beat)||double.IsInfinity(c.Beat)||c.Beat<0||c.Source<0||c.Source>=s.Sources.Count))throw new Exception("Réglages du sélecteur/mélangeur invalides.");}
 internal static void Migrate(Graph15 graph){foreach(var n in graph.Nodes.Where(n=>n.Kind==GraphKind15.Mixer)){if(n.MixerR20==null){n.MixerR20=new MixerSettingsR20{Hardness=0,LegacyAB=true};var links=graph.Wires.Where(w=>w.To==n.Id&&(w.Port==GraphPort15.Video||w.Port==GraphPort15.VideoB)).OrderBy(w=>w.Port==GraphPort15.VideoB?1:0).ThenBy(w=>w.Order).ToArray();for(int i=0;i<links.Length;i++)n.MixerR20.Sources.Add(new MixerSourceR20{Node=links[i].From,Min=128.0*i/links.Length,Max=128.0*(i+1)/links.Length-1});}foreach(var wire in graph.Wires.Where(w=>w.To==n.Id&&w.Port==GraphPort15.VideoB).ToArray()){if(graph.Wires.Any(w=>w!=wire&&w.From==wire.From&&w.To==wire.To&&w.Port==GraphPort15.Video))graph.Wires.Remove(wire);else wire.Port=GraphPort15.Video;}}}

 internal static double[] Weights(MixerSettingsR20 settings,double value){var rows=settings.Sources;var result=new double[rows.Count];if(rows.Count==0)return result;if(settings.LegacyAB&&rows.Count==2){result[1]=Math.Max(0,Math.Min(1,value/127));result[0]=1-result[1];return result;}int hit=rows.FindIndex(r=>value>=r.Min&&value<=r.Max);if(hit<0)hit=Enumerable.Range(0,rows.Count).OrderBy(i=>Math.Min(Math.Abs(value-rows[i].Min),Math.Abs(value-rows[i].Max))).First();result[hit]=1;if(settings.Hardness>=1)return result;var sorted=Enumerable.Range(0,rows.Count).OrderBy(i=>rows[i].Min).ToArray();for(int j=0;j<sorted.Length-1;j++){int a=sorted[j],b=sorted[j+1];double border=(rows[a].Max+rows[b].Min)/2,width=Math.Max(.001,Math.Min(rows[a].Max-rows[a].Min+1,rows[b].Max-rows[b].Min+1)/2)*(1-settings.Hardness);if(value<border-width||value>border+width)continue;Array.Clear(result,0,result.Length);double ratio=(value-border+width)/(2*width);result[a]=1-ratio;result[b]=ratio;break;}return result;}
}
internal sealed partial class GraphRun15 {
 readonly Dictionary<string,List<GraphEvent15>> mixerNotesR20=new Dictionary<string,List<GraphEvent15>>();
 readonly Dictionary<string,List<GraphEvent15>> conditionStreamsR20=new Dictionary<string,List<GraphEvent15>>();
 Bitmap MixR20(GraphNode15 node,GraphWire15[] incoming,Dictionary<string,Bitmap> frames,Dictionary<string,double> opacity,double time,int width,int height,double? controlValue){var settings=node.MixerR20;int count=settings.Sources.Count;var result=Blank(width,height);if(count==0||!ConditionR20.At(node.ConditionR20,conditionStreamsR20[node.Id],time))return result;var cues=settings.Mode==MixerModeR20.Valeur_MIDI?MixerEventsR21(node):activations[node.Id];double[] weights;var cue=GraphEvents15.Latest(cues,time);if(settings.Mode==MixerModeR20.Valeur_MIDI)weights=MixerR20.Weights(settings,controlValue.HasValue?controlValue.Value*127:cue==null?node.Mix*127:node.ActivationR4.Value(cue)*127);else{int index=0,previous=0;double since=0;if(settings.Mode==MixerModeR20.Cycle){double beat=graphClock.Available?graphClock.Beat(time)-graphClock.Beat(blockOriginR19):(time-blockOriginR19)*2;int step=(int)Math.Floor(Math.Max(0,beat)/settings.Cycle);index=step%count;previous=(step+count-1)%count;since=graphClock.Available?time-graphClock.Time(graphClock.Beat(blockOriginR19)+step*settings.Cycle):time-blockOriginR19-step*settings.Cycle/2;if(step==0)previous=index;}else if(settings.Mode==MixerModeR20.Notes_successives){List<GraphEvent15> notes;if(!mixerNotesR20.TryGetValue(node.Id,out notes)){notes=cues.Where(e=>e.Kind=="NoteOn"&&e.Time>=blockOriginR19).ToList();mixerNotesR20[node.Id]=notes;}int lo=0,hi=notes.Count;while(lo<hi){int mid=(lo+hi)/2;if(notes[mid].Time<=time)lo=mid+1;else hi=mid;}index=lo%count;previous=Math.Max(0,lo-1)%count;since=lo==0?settings.Transition:time-notes[lo-1].Time;}else{var beat=graphClock.Available?graphClock.Beat(time)-graphClock.Beat(blockOriginR19):(time-blockOriginR19)*2;var list=settings.Cues.Where(c=>c.Beat<=beat).OrderBy(c=>c.Beat).ToArray();if(list.Length>0){index=Math.Max(0,Math.Min(count-1,list.Last().Source));previous=list.Length<2?0:Math.Max(0,Math.Min(count-1,list[list.Length-2].Source));since=graphClock.Available?time-graphClock.Time(graphClock.Beat(blockOriginR19)+list.Last().Beat):(beat-list.Last().Beat)/2;}}weights=new double[count];double duration=settings.Transition*(1-settings.Hardness),ratio=duration<=0?1:Math.Max(0,Math.Min(1,since/duration));weights[previous]+=1-ratio;weights[index]+=ratio;}if(node.MutedR4){Array.Clear(weights,0,weights.Length);weights[0]=1;}double total=0;for(int i=0;i<count;i++){if(weights[i]<=0||!incoming.Any(w=>w.From==settings.Sources[i].Node)||!frames.ContainsKey(settings.Sources[i].Node))continue;string key=settings.Sources[i].Node;double next=total+weights[i];var mixed=TboSignal15.Mix(result,1,frames[key],opacity[key],weights[i]/next);result.Dispose();result=mixed;total=next;}if(total>0&&total<1){using(var blank=Blank(width,height)){var adjusted=TboSignal15.Mix(blank,1,result,1,total);result.Dispose();result=adjusted;}}return result;}
}
